package com.vibehopper.infrastructure.persistence.event;
import com.vibehopper.domain.event.*; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.geo.GeoJsonPoint; import org.springframework.data.mongodb.core.index.*; import org.springframework.data.mongodb.core.mapping.Document; import java.time.*; import java.util.List;
@Document(collection="events") @CompoundIndex(name="source_identity_idx", def="{'source.sourceName': 1, 'source.externalId': 1}") @CompoundIndex(name="normalized_identity_idx", def="{'normalizedName': 1, 'date': 1, 'normalizedCity': 1}")
public class EventDocument {
    @Id private String id; private String city; private String normalizedCity; private String description; private String address; private String name; private String normalizedName; private List<String> keywords; private Category category; private CountryCode countryCode; private String host; private String ownerId; private LocalDate created; private LocalDate updated; private boolean recurring; private LocalDate date; private WeekDays weekday; private LocalTime startsAt; private LocalTime endsAt; private int capacity; private boolean passed; private boolean active; private boolean cancelled; private List<String> images; private List<String> attendees; private EventSourceDocument source; @GeoSpatialIndexed(type = GeoSpatialIndexType.GEO_2DSPHERE) private GeoJsonPoint coordinates;
    public String getId(){return id;} public void setId(String id){this.id=id;} public String getCity(){return city;} public void setCity(String city){this.city=city;} public String getNormalizedCity(){return normalizedCity;} public void setNormalizedCity(String normalizedCity){this.normalizedCity=normalizedCity;} public String getDescription(){return description;} public void setDescription(String description){this.description=description;} public String getAddress(){return address;} public void setAddress(String address){this.address=address;} public String getName(){return name;} public void setName(String name){this.name=name;} public String getNormalizedName(){return normalizedName;} public void setNormalizedName(String normalizedName){this.normalizedName=normalizedName;} public List<String> getKeywords(){return keywords;} public void setKeywords(List<String> keywords){this.keywords=keywords;} public Category getCategory(){return category;} public void setCategory(Category category){this.category=category;} public CountryCode getCountryCode(){return countryCode;} public void setCountryCode(CountryCode countryCode){this.countryCode=countryCode;} public String getHost(){return host;} public void setHost(String host){this.host=host;} public String getOwnerId(){return ownerId;} public void setOwnerId(String ownerId){this.ownerId=ownerId;} public LocalDate getCreated(){return created;} public void setCreated(LocalDate created){this.created=created;} public LocalDate getUpdated(){return updated;} public void setUpdated(LocalDate updated){this.updated=updated;} public boolean isRecurring(){return recurring;} public void setRecurring(boolean recurring){this.recurring=recurring;} public LocalDate getDate(){return date;} public void setDate(LocalDate date){this.date=date;} public WeekDays getWeekday(){return weekday;} public void setWeekday(WeekDays weekday){this.weekday=weekday;} public LocalTime getStartsAt(){return startsAt;} public void setStartsAt(LocalTime startsAt){this.startsAt=startsAt;} public LocalTime getEndsAt(){return endsAt;} public void setEndsAt(LocalTime endsAt){this.endsAt=endsAt;} public int getCapacity(){return capacity;} public void setCapacity(int capacity){this.capacity=capacity;} public boolean isPassed(){return passed;} public void setPassed(boolean passed){this.passed=passed;} public boolean isActive(){return active;} public void setActive(boolean active){this.active=active;} public boolean isCancelled(){return cancelled;} public void setCancelled(boolean cancelled){this.cancelled=cancelled;} public List<String> getImages(){return images;} public void setImages(List<String> images){this.images=images;} public List<String> getAttendees(){return attendees;} public void setAttendees(List<String> attendees){this.attendees=attendees;} public EventSourceDocument getSource(){return source;} public void setSource(EventSourceDocument source){this.source=source;} public GeoJsonPoint getCoordinates(){return coordinates;} public void setCoordinates(GeoJsonPoint coordinates){this.coordinates=coordinates;}
    public static class EventSourceDocument { private SourceType sourceType; private String sourceName; private String externalId; private String sourceUrl; private Instant lastSyncedAt; public SourceType getSourceType(){return sourceType;} public void setSourceType(SourceType sourceType){this.sourceType=sourceType;} public String getSourceName(){return sourceName;} public void setSourceName(String sourceName){this.sourceName=sourceName;} public String getExternalId(){return externalId;} public void setExternalId(String externalId){this.externalId=externalId;} public String getSourceUrl(){return sourceUrl;} public void setSourceUrl(String sourceUrl){this.sourceUrl=sourceUrl;} public Instant getLastSyncedAt(){return lastSyncedAt;} public void setLastSyncedAt(Instant lastSyncedAt){this.lastSyncedAt=lastSyncedAt;} }
}
